css:
body :where([data-bz-node="cs"]) .bz-block{padding:0}
body :where([data-bz-node="cs"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="cs"]>.bz-container{padding-inline:0}

body [data-bz-node="cs"]{background:#fff;padding:90px 0}
body [data-bz-node="cs"]>.bz-container{max-width:var(--container)}
body [data-bz-node="cs-row"]{display:grid;grid-template-columns:1fr 1fr;gap:0 64px;align-items:center}
body [data-bz-node="cs-copy"],body [data-bz-node="cs-media"]{grid-column:auto}
body [data-bz-node="cs-h"] h2{font:700 36px/1.1 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0;max-width:520px}
body [data-bz-node="cs-text"] .bz-text{max-width:520px;margin-top:24px}
body [data-bz-node="cs-text"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0 0 14px}
body [data-bz-node="cs-text"] p:last-child{margin:0}
body [data-bz-node="cs-media"] figure{margin:0}
body [data-bz-node="cs-media"] img{width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:0}
@media (max-width:1100px){body [data-bz-node="cs"]{padding:64px 24px}body [data-bz-node="cs-row"]{grid-template-columns:1fr;gap:32px}body [data-bz-node="cs-h"] h2{font-size:30px}}
@media (max-width:640px){body [data-bz-node="cs"]{padding:48px 20px}body [data-bz-node="cs-h"] h2{font-size:26px}}
